/** [sql-cigmaInterface.xml] CigmaInterfaceMapper.insertDmes18 **/
INSERT INTO DMES_18 (
					  CHLLOT
					, CHLRTG
					, CHLDTS
					, CHLLIN
					, CHLHOU
					, CHLPNS
					, CHLQYS
					, CHLIDS
) VALUES (
		   #{st02Lot}
		 , 'I'
		 , TO_CHAR(SYSDATE, 'YYYYMMDD')
		 , #{line}
		 , '1'
		 , #{st02Code}
		 , #{st02Moq}
		 , 'LOTMGR'
		 )

